26: public:
27:     Async(Parent* parent_, Callback cb_)
28:         : callback(cb_), parent(parent_) {
29:         watcher.data = this;
30:         NODE_SQLITE3_MUTEX_INIT
31:         uv_loop_t *loop;
32:         napi_get_uv_event_loop(parent_->Env(), &loop);
33:         uv_async_init(loop, &watcher, reinterpret_cast<uv_async_cb>(listener));
34:     }
