36:     static void listener(uv_async_t* handle) {
37:         Async* async = static_cast<Async*>(handle->data);
38:         std::vector<Item*> rows;
39:         NODE_SQLITE3_MUTEX_LOCK(&async->mutex)
40:         rows.swap(async->data);
41:         NODE_SQLITE3_MUTEX_UNLOCK(&async->mutex)
42:         for (unsigned int i = 0, size = rows.size(); i < size; i++) {
43:             async->callback(async->parent, rows[i]);
44:         }
45:     }
46: 
47:     static void close(uv_handle_t* handle) {
48:         assert(handle != NULL);
49:         assert(handle->data != NULL);
50:         Async* async = static_cast<Async*>(handle->data);
51:         delete async;
52:     }
53: 
54:     void finish() {
55:         // Need to call the listener again to ensure all items have been
56:         // processed. Is this a bug in uv_async? Feels like uv_close
57:         // should handle that.
58:         listener(&watcher);
59:         uv_close((uv_handle_t*)&watcher, close);
60:     }
