15:       InstanceMethod("bind", &Statement::Bind),
16:       InstanceMethod("get", &Statement::Get),
17:       InstanceMethod("run", &Statement::Run),
18:       InstanceMethod("all", &Statement::All),
19:       InstanceMethod("each", &Statement::Each),
20:       InstanceMethod("reset", &Statement::Reset),
