28: // A Napi InstanceOf for Javascript Objects "Date" and "RegExp"
29: bool OtherInstanceOf(Napi::Object source, const char* object_type) {
30:     if (strncmp(object_type, "Date", 4) == 0) {
31:         return source.InstanceOf(source.Env().Global().Get("Date").As<Function>());
32:     } else if (strncmp(object_type, "RegExp", 6) == 0) {
33:         return source.InstanceOf(source.Env().Global().Get("RegExp").As<Function>());
34:     }
35: 
36:     return false;
