39: void Statement::Process() {
40:     if (finalized && !queue.empty()) {
41:         return CleanQueue();
42:     }
43: 
44:     while (prepared && !locked && !queue.empty()) {
45:         std::unique_ptr<Call> call(queue.front());
46:         queue.pop();
47: 
48:         call->callback(call->baton);
49:     }
50: }
