52: void Statement::Schedule(Work_Callback callback, Baton* baton) {
53:     if (finalized) {
54:         queue.push(new Call(callback, baton));
55:         CleanQueue();
56:     }
57:     else if (!prepared || locked) {
58:         queue.push(new Call(callback, baton));
59:     }
60:     else {
61:         callback(baton);
62:     }
63: }
