65: template <class T> void Statement::Error(T* baton) {
66:     Statement* stmt = baton->stmt;
67: 
68:     Napi::Env env = stmt->Env();
69:     Napi::HandleScope scope(env);
70: 
71:     // Fail hard on logic errors.
72:     assert(stmt->status != 0);
73:     EXCEPTION(Napi::String::New(env, stmt->message.c_str()), stmt->status, exception);
74: 
75:     Napi::Function cb = baton->callback.Value();
76: 
77:     if (!cb.IsUndefined() && cb.IsFunction()) {
78:         Napi::Value argv[] = { exception };
79:         TRY_CATCH_CALL(stmt->Value(), cb, 1, argv);
80:     }
81:     else {
82:         Napi::Value argv[] = { Napi::String::New(env, "error"), exception };
83:         EMIT_EVENT(stmt->Value(), 2, argv);
