118: void Statement::Work_BeginPrepare(Database::Baton* baton) {
119:     assert(baton->db->open);
120:     baton->db->pending++;
121:     Napi::Env env = baton->db->Env();
122:     int status = napi_create_async_work(
123:         env, NULL, Napi::String::New(env, "sqlite3.Statement.Prepare"),
124:         Work_Prepare, Work_AfterPrepare, baton, &baton->request
125:     );
126:     assert(status == 0);
127:     napi_queue_async_work(env, baton->request);
128: }
