130: void Statement::Work_Prepare(napi_env e, void* data) {
131:     STATEMENT_INIT(PrepareBaton);
132: 
133:     // In case preparing fails, we use a mutex to make sure we get the associated
134:     // error message.
135:     STATEMENT_MUTEX(mtx);
136:     sqlite3_mutex_enter(mtx);
137: 
138:     stmt->status = sqlite3_prepare_v2(
139:         baton->db->_handle,
140:         baton->sql.c_str(),
141:         baton->sql.size(),
142:         &stmt->_handle,
143:         NULL
144:     );
145: 
146:     if (stmt->status != SQLITE_OK) {
147:         stmt->message = std::string(sqlite3_errmsg(baton->db->_handle));
148:         stmt->_handle = NULL;
149:     }
150: 
151:     sqlite3_mutex_leave(mtx);
