271: bool Statement::Bind(const Parameters & parameters) {
272:     if (parameters.size() == 0) {
273:         return true;
274:     }
275: 
276:     sqlite3_reset(_handle);
277:     sqlite3_clear_bindings(_handle);
278: 
279:     Parameters::const_iterator it = parameters.begin();
280:     Parameters::const_iterator end = parameters.end();
281: 
282:     for (; it < end; ++it) {
283:         Values::Field* field = *it;
284: 
285:         if (field != NULL) {
286:             unsigned int pos;
287:             if (field->index > 0) {
288:                 pos = field->index;
289:             }
290:             else {
291:                 pos = sqlite3_bind_parameter_index(_handle, field->name.c_str());
292:             }
293: 
294:             switch (field->type) {
295:                 case SQLITE_INTEGER: {
296:                     status = sqlite3_bind_int(_handle, pos,
297:                         ((Values::Integer*)field)->value);
298:                 } break;
299:                 case SQLITE_FLOAT: {
300:                     status = sqlite3_bind_double(_handle, pos,
301:                         ((Values::Float*)field)->value);
302:                 } break;
303:                 case SQLITE_TEXT: {
304:                     status = sqlite3_bind_text(_handle, pos,
305:                         ((Values::Text*)field)->value.c_str(),
306:                         ((Values::Text*)field)->value.size(), SQLITE_TRANSIENT);
307:                 } break;
308:                 case SQLITE_BLOB: {
309:                     status = sqlite3_bind_blob(_handle, pos,
310:                         ((Values::Blob*)field)->value,
311:                         ((Values::Blob*)field)->length, SQLITE_TRANSIENT);
312:                 } break;
313:                 case SQLITE_NULL: {
314:                     status = sqlite3_bind_null(_handle, pos);
315:                 } break;
316:             }
317: 
318:             if (status != SQLITE_OK) {
319:                 message = std::string(sqlite3_errmsg(db->_handle));
320:                 return false;
321:             }
322:         }
323:     }
324: 
325:     return true;
326: }
