576:     }
577:     else {
578:         // Fire callbacks.
579:         Napi::Function cb = baton->callback.Value();
580:         if (!cb.IsUndefined() && cb.IsFunction()) {
581:             if (baton->rows.size()) {
582:                 // Create the result array from the data we acquired.
583:                 Napi::Array result(Napi::Array::New(env, baton->rows.size()));
584:                 Rows::const_iterator it = baton->rows.begin();
585:                 Rows::const_iterator end = baton->rows.end();
586:                 for (int i = 0; it < end; ++it, i++) {
587:                     std::unique_ptr<Row> row(*it);
